def evaluate_results(real_data, synthetic_datasets, performance_logs, config):

    # 1. Initialize result container
    results = {}

    # 2. Loop over synthetic datasets
    for rep, synth in enumerate(synthetic_datasets):
        r = {}

        # 2.1 Marginal Distribution
        for c in continuous_columns:
            r.setdefault(c, {}).update({
                "wasserstein": compute_wasserstein(real_data[c], synth[c]),
                "ks": compute_ks(real_data[c], synth[c])
            })

        for c in categorical_columns:
            r.setdefault(c, {}).update({
                "js": compute_js_divergence(real_data[c], synth[c]),
                "kl": compute_kl_divergence(real_data[c], synth[c])
            })

        # 2.2 Dependency Structure
        pairs = create_fixed_column_pairs(real_data.columns)
        r["dependency"] = {
            (a, b): {
                "pearson": compute_corr_diff(),
                "spearman": compute_corr_diff(),
                "kendall": compute_corr_diff(),
                "point_biserial": compute_corr_diff()
            }
            for a, b in pairs
        }

        # 2.3 Robustness
        r["robustness"] = compute_robustness_metrics(real_data, synth)

        # 2.4 Privacy Preservation
        r["privacy"] = {
            "dcr": compute_dcr(real_data, synth),
            "nndr": compute_nndr(real_data, synth)
        }

        # 2.5 Utility
        if problem_type == "classification":
            r["utility"] = run_classifiers(real_data, synth, target_column)
        else:
            r["utility"] = run_regressors(real_data, synth, target_column)

        # 2.6 Computational Performance
        r["performance"] = evaluate_performance(performance_logs[rep])

        results[rep] = r

    # 3. Aggregate and save
    aggregated_results = aggregate_metrics(results)
    return aggregated_results
